    content:
      "# How Audience matches people, the traits it keeps and the products it is linked to. This file is the only place they\n# are set; a change is picked up within a minute, and a file with a mistake leaves the last good one in place.\n#\n# Two records are one person when they share an email, a phone number or your user id, and only then.\nmatch_by: [email, phone, user_id] # never device fingerprints, never IP addresses\nphone_country: TR # numbers written without a country code, such as 0555 111 22 33, are +90\n\ntraits:\n  plan: { values: [Free, Pro, Business], from: [api, crm, import] }\n  city: { from: [forms, import, api] }\n  sector: { from: [crm, forms, import] }\n  company: {}\n  renewal_date: { type: date, from: [crm, api] }\n\n# The linked products. token names the environment variable that holds that product's API token, never the token.\n# url is where Audience calls it; without it, the product's address in OPENASY_PRODUCTS.\nsources:\n  analytics:\n    token: AUDIENCE_ANALYTICS_TOKEN # an admin token of Analytics: it reads visits and deletes visitors\n    sites: [shop] # identified visitors of these sites become profiles\n  consent:\n    token: AUDIENCE_CONSENT_TOKEN # an admin token of Consent: profiles show what people agreed to; deletions reach it\n  # forms: true                          # Forms sends its events; nothing is deleted there\n  # crm: { token: AUDIENCE_CRM_TOKEN }   # CRM sends its events, and people deleted here are deleted there\n  # messages: { token: AUDIENCE_MESSAGES_TOKEN }\n\nevents:\n  keep: 25mo # older events are deleted; the profile stays\n\nsegments:\n  recount: 15m # every segment is counted in full this often (or nightly); people join and leave as they act in between",
