      "# Who messages come from, the providers each channel sends through, how consent is checked and the linked products.\n# This file is the only place they are set; a change is picked up within a minute, and a file with a mistake leaves\n# the last good one in place. Keys are never written here: each one names the environment variable that holds it.\nsender:\n  name: Acme Books\n  email: hello@example.com # the address emails come from; verified in SES, or allowed by your SMTP server\n  reply_to: support@example.com\n  address: Acme Books A.Ş., Kızılay, Ankara # shown at the foot of every email\n\nproviders:\n  email:\n    primary:\n      kind: ses # Amazon SES, its v2 API\n      region: eu-central-1\n      access_key: MESSAGES_SES_ACCESS_KEY\n      secret_key: MESSAGES_SES_SECRET_KEY\n      configuration_set: messages # publishes bounces, complaints and deliveries to the SNS topic below\n      sns_topic: arn:aws:sns:eu-central-1:123456789012:messages\n      rate: 14 # messages a second, at most: your SES sending rate\n    fallback: # used only when SES surely did not take a message (it could not be reached, or answered 5xx)\n      kind: smtp\n      host: smtp.example.com\n      port: 587 # STARTTLS; 465 is TLS from the start\n      user: MESSAGES_SMTP_USER\n      password: MESSAGES_SMTP_PASSWORD\n      rate: 5\n  sms:\n    kind: netgsm # or iletimerkezi, with key: and secret:\n    sender: ACME # your approved sender name (başlık)\n    user: MESSAGES_NETGSM_USER\n    password: MESSAGES_NETGSM_PASSWORD\n    stop: \"İptal için RET yazıp 4609'a gönderin.\" # added to every SMS that does not say it already\n    rate: 20\n  whatsapp:\n    kind: whatsapp # the WhatsApp Business Cloud API; only templates Meta approved are sent\n    phone_number_id: \"109876543210\"\n    business_account_id: \"209876543210\"\n    token: MESSAGES_WHATSAPP_TOKEN\n    app_secret: MESSAGES_WHATSAPP_APP_SECRET # checks the webhook's signature\n    verify_token: MESSAGES_WHATSAPP_VERIFY_TOKEN # what you type in Meta's webhook settings\n\nconsent:\n  check: consent # ask Consent before every message; own: Messages' own opt-out list alone\n  purpose: marketing # the purpose in consent.yaml the messages are for\n  whatsapp: sms # Consent has no WhatsApp channel: the SMS answer counts for it (as İYS's MESAJ does)\n\nproducts:\n  consent: { token: MESSAGES_CONSENT_TOKEN } # an editor token of Consent: it checks, and records unsubscribes and STOPs\n  audience: { token: MESSAGES_AUDIENCE_TOKEN } # an editor token of Audience: segments to send to, and Messages' events\n\nlimits:\n  quiet_hours: 21:00-09:00 # SMS and WhatsApp wait; email does not\n  timezone: Europe/Istanbul\n  soft_bounce_tries: 3 # an address that soft-bounces this many times in a row is treated as a hard bounce\n\ntracking:\n  opens: true\n  clicks: true # links go through Messages, which counts the click and sends the person on\n  utm_source: messages # with utm_medium (the channel) and utm_campaign (the campaign), which Analytics keeps",
